// Zero-dependency, XSS-safe markdown renderer for the ELIZA-AI web UI.
// Local-first: no CDN, no npm packages. Renders the subset LLMs emit most:
// headings, bold/italic/strikethrough, inline + fenced code, lists (incl.
// task lists + nesting), blockquotes, hr, links, images, tables, paragraphs.
//
// Safety model: raw HTML is NEVER passed through. Everything is escaped
// first; only tags generated by this renderer exist in the output. URLs are
// allow-listed (http/https/mailto/anchor/relative); anything else (e.g.
// `javascript:`, `data:`) degrades to plain text.

export function escHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => {
    switch (c) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case '"': return "&quot;";
      case "'": return "&#39;";
      default: return c;
    }
  });
}

function isSafeUrl(url: string): boolean {
  const u = url.trim();
  if (!u) return false;
  if (u.startsWith("#") || u.startsWith("/") || u.startsWith("./") || u.startsWith("../")) return true;
  if (/^[a-zA-Z0-9._~:/?#[\]@!$&'()*+,;=%-]+$/.test(u) === false) {
    // Allow unicode-ish URLs too; only block control chars / spaces / quotes.
    if (/[\s<>"'`]/.test(u)) return false;
  }
  const lower = u.toLowerCase();
  if (lower.startsWith("https://") || lower.startsWith("http://") || lower.startsWith("mailto:")) return true;
  // Relative URL without scheme (e.g. `docs/guide`, `page.html?a=b`).
  if (/^[a-z0-9._~/?#[\]@!$&'()*+,;=%-]+$/i.test(u) && !/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(u)) return true;
  return false;
}

